-- PulseCart evaluation dump  |  import in MySQL Workbench
-- File > Run SQL Script
DROP DATABASE IF EXISTS pulsecart;
CREATE DATABASE pulsecart;
USE pulsecart;
CREATE TABLE products (
  product_id INT PRIMARY KEY,
  sku VARCHAR(32),
  product_name VARCHAR(64),
  category VARCHAR(32),
  unit_cost DECIMAL(10,2),
  list_price DECIMAL(10,2)
);
CREATE TABLE customers (
  customer_id INT PRIMARY KEY,
  first_name VARCHAR(40),
  last_name VARCHAR(40),
  email VARCHAR(120),
  phone VARCHAR(32),
  city VARCHAR(40),
  state VARCHAR(8),
  signup_date DATE,
  plan VARCHAR(16),
  age INT NULL,
  last_active_date DATE,
  churned TINYINT
);
CREATE TABLE orders (
  order_id INT PRIMARY KEY,
  customer_id INT,
  product_id INT,
  order_date DATE,
  channel VARCHAR(16),
  quantity INT,
  unit_price DECIMAL(10,2),
  discount_pct DECIMAL(6,2),
  returned TINYINT,
  status VARCHAR(16)
);
CREATE TABLE support_tickets (
  ticket_id INT PRIMARY KEY,
  customer_id INT,
  order_id INT,
  created_at DATETIME,
  ticket_type VARCHAR(32) NULL,
  priority VARCHAR(16),
  raw_message TEXT,
  resolved TINYINT
);
SELECT 'pulsecart loaded' AS status, COUNT(*) AS customers FROM customers;